import fs from 'node:fs';
import path from 'node:path';
import {OUT,normalize,compatible,seriesMatch} from './import-ryco-filter-fitments-20261025.mjs';
const read=n=>JSON.parse(fs.readFileSync(path.join(OUT,n),'utf8'));
const p=read('plan.json'),source=read('source.json').rows.map(normalize).filter(r=>['oil_filter','air_filter'].includes(r.type));
const compact=v=>String(v??'').toUpperCase().replace(/[^A-Z0-9]/g,'');
const uniq=v=>[...new Set(v)];
const byApp=new Map(p.apps.map(a=>[a.application_id,a]));
const rows=p.review.map(q=>{
 const a=byApp.get(q.application_id),rr=source.filter(r=>r.family===a.family&&r.type===q.type),yearRows=rr.filter(r=>a.years.some(y=>y>=r.from&&y<=r.to));
 const exact=rr.filter(r=>compatible(a,r)),covered=a.years.filter(y=>exact.some(r=>y>=r.from&&y<=r.to));
 const engine=yearRows.filter(r=>r.engineCode&&a.engine_codes.length&&a.engine_codes.every(c=>compact(c)===r.engineCode));
 const series=engine.filter(r=>r.seriesTokens.length?seriesMatch(a,r):q.type==='oil_filter');
 let reason;
 if(covered.length)reason='partial_application_years';
 else if(!yearRows.length)reason='outside_source_years';
 else if(!a.engine_codes.length&&/^electric$/i.test(a.engine))reason='not_applicable_pure_electric';
 else if(!a.engine_codes.length)reason='catalog_engine_code_missing';
 else if(!engine.length&&yearRows.some(r=>!r.engineCode))reason='source_engine_code_not_structured';
 else if(!engine.length)reason='engine_not_in_source_for_years';
 else if(!series.length)reason='series_not_matched';
 else reason='body_drive_or_other_conditions';
 return {...q,reason_detail:reason,application_years:a.years,matched_years:covered,unmatched_years:a.years.filter(y=>!covered.includes(y)),source_model_years:[Math.min(...rr.map(r=>r.from)),Math.max(...rr.map(r=>r.to))],application_engine_codes:a.engine_codes,candidate_references:uniq(exact.map(r=>r.reference)),source_engine_codes:uniq(yearRows.map(r=>r.engineCode).filter(Boolean)),source_series:uniq(engine.map(r=>r.series))};
});
const reasons=uniq(rows.map(r=>r.reason_detail)).map(reason=>({reason,oil_filter:rows.filter(r=>r.reason_detail===reason&&r.type==='oil_filter').length,air_filter:rows.filter(r=>r.reason_detail===reason&&r.type==='air_filter').length}));
const six=['COROLLA','HILUX','LAND CRUISER','RANGER','RAV4','SWIFT'];
const modelCounts=six.map(model=>({model,oil_filter:rows.filter(r=>r.model===model&&r.type==='oil_filter').length,air_filter:rows.filter(r=>r.model===model&&r.type==='air_filter').length}));
const examples=uniq(rows.map(r=>r.reason_detail)).map(reason=>rows.find(r=>r.reason_detail===reason&&six.includes(r.model))??rows.find(r=>r.reason_detail===reason));
const report={generated_at:new Date().toISOString(),definition:'Application × product line not published by this batch; includes out-of-source coverage, not 3997 erroneous source rows',total:rows.length,unique_applications:uniq(rows.map(r=>r.application_id)).length,reasons,six_full_workbook_models:modelCounts,other_models:rows.filter(r=>!six.includes(r.model)).length,examples,rows};
fs.writeFileSync(path.join(OUT,'review-diagnosis.json'),JSON.stringify(report,null,2));
console.log(JSON.stringify({...report,rows:undefined},null,2));
